// === Tab: mySketch ===
// Translated to P5.js

let newStar;
let starArray = [];
let h2, w2, d2; 
const numberOfStars = 20000; 
const newStars = 50; 

function setup() {
  createCanvas(windowWidth, windowHeight);
  w2 = width / 2;
  h2 = height / 2;
  d2 = dist(0, 0, w2, h2);
  noStroke();
  newStar = new Star();
  background(0);
}

function draw() {
  fill(0, map(dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), w2, h2), 0, d2, 255, -10));
  rect(0, 0, width, height);

	//以下の二つのif文で、星の図形が中心に集まっているときはチャージのような感じで暗く点滅し、星の図形が外に広がるときは明るく、あまり点滅しないようにしている
	if((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) <= width/2){
		 fill(random(50,150));
	}
	if((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) >= width/2){
		 fill(random(200,255));
	}
  newStar.render();

  // Add new stars
  for (let i = 0; i < newStars; i++) {
    starArray.push(new Star());
  }

  // Update and render stars, remove if out of bounds
  for (let i = starArray.length - 1; i >= 0; i--) {
    let star = starArray[i];
    if (star.x < 0 || star.x > width || star.y < 0 || star.y > height) {
      starArray.splice(i, 1);
    } else {
      star.move();
      star.render();
    }
  }

  // Limit the number of stars
  if (starArray.length > numberOfStars) {
    starArray.splice(0, newStars);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  w2 = width / 2;
  h2 = height / 2;
  d2 = dist(0, 0, w2, h2);
}

// === Tab: star class ===
class Star {
  constructor() {
    this.x = random(width);
    this.y = random(height);
    this.speed = random(0.2, 5);
    this.grow = int(random(0, 2));
    this.d = this.grow === 1 ? 0 : random(0.2, 3);
    this.age = 0;
    this.sizeIncr = random(0, 0.03);
  }

  render() {
    this.age++;
    if (this.age < 200) {
      if (this.grow === 1) {
        this.d += this.sizeIncr;
        if (this.d > 3 || this.d < -3) this.d = 3;
      } else {
        if (this.d > 3 || this.d < -3) this.d = 3;
        this.d = this.d + 0.2 - 0.6 * noise(this.x, this.y, frameCount * 0.001);
      }
    } else {
      if (this.d > 3 || this.d < -3) this.d = 3;
    }
    ellipse(
      this.x,
      this.y,
      this.d * map(noise(this.x, this.y, 0.001 * frameCount), 0, 1, 0.2, 1.5),
      this.d * map(noise(this.x, this.y, 0.001 * frameCount), 0, 1, 0.2, 1.5)
    );
  }

  move() {
    this.x = this.x - map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -0.05 * this.speed, 0.05 * this.speed) * (w2 - this.x);
    this.y = this.y - map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -0.05 * this.speed, 0.05 * this.speed) * (h2 - this.y);
  }
}

